import json,hashlib,re
from pathlib import Path
import fitz
R=Path(__file__).resolve().parents[3]
P=R/'data/question-visuals/crop-plan-late-additions.json';O=R/'audits/question-visuals/late-decision-overrides.json';S=R/'audits/question-visuals/late-source-overrides.json'
plans=json.loads(P.read_text()) if P.exists() else {};overrides=json.loads(O.read_text()) if O.exists() else {};sources=json.loads(S.read_text()) if S.exists() else {}
def crop(page,rect,suffix='',alt=None):
 key=f'lectures-p{page:04}'+suffix
 plans[key]={'sourceId':'lectures','physicalPage':page,'cropRectangle':rect,'renderDpi':216,'alt':alt or f'Exact source input crop from lecture PDF, physical page {page}.'}
 return key
def bind(q,keys,reason='The full source instance referenced by the question is required; the crop preserves its input values, labels and structure without supplying a worked solution.'):
 if isinstance(keys,int):keys=[f'lectures-p{keys:04}']
 sources[q]=sorted({plans[k]['physicalPage'] for k in keys})
 overrides[q]={'dependencyStatus':'required','reason':reason,'requiredInputs':['Source figure, code, table or mathematical input referenced by the question.'],'cropKeys':keys}
def self_contained(q,reason):overrides[q]={'dependencyStatus':'self_contained','reason':reason}
def default_bind(pages):
 m=json.loads((R/'data/question-visuals/manifest.json').read_text())
 for r in m['records']:
  if not re.search(r'-L(3[6-9]|[45]\d|60)-',r['questionId']) or r['dependencyStatus']!='required' or r['questionId'] in overrides:continue
  refs={x['physicalPage'] for x in r['sourceRefs']};keys=[f'lectures-p{p:04}' for p in sorted(refs&set(pages)) if f'lectures-p{p:04}' in plans]
  if keys:bind(r['questionId'],keys)
def save(render=True):
 for path,data in [(P,plans),(O,overrides),(S,sources)]:path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
 if render:
  doc=fitz.open(R/'sources/raw/AI_for_Robotics_All_Lectures.pdf')
  for key,p in plans.items():
   dest=R/f'assets/question-visuals/{key}.png';rect=fitz.Rect(p['cropRectangle']);pg=doc[p['physicalPage']-1];assert rect in pg.rect,(key,rect)
   pix=pg.get_pixmap(matrix=fitz.Matrix(3,3),clip=rect,alpha=False);pix.save(dest)
 print('plans',len(plans),'decisions',len(overrides),'required',sum(x['dependencyStatus']=='required' for x in overrides.values()))
